class Komut:
    def uygula(self, g): raise NotImplementedError
    def geri_al(self, g): raise NotImplementedError
    def __repr__(self): return type(self).__name__


class TarifeDegistir(Komut):
    def __init__(self, yeni): self.yeni, self.eski = yeni, None
    def uygula(self, g):
        self.eski = g["tarife"]
        g["tarife"] = self.yeni
    def geri_al(self, g):
        g["tarife"] = self.eski


class KalemEkle(Komut):
    def __init__(self, ad): self.ad = ad
    def uygula(self, g): g["kalemler"].append(self.ad)
    def geri_al(self, g): g["kalemler"].remove(self.ad)


class Makro(Komut):
    def __init__(self, *komutlar): self.komutlar = list(komutlar)
    def uygula(self, g):
        for k in self.komutlar: k.uygula(g)
    def geri_al(self, g):
        for k in reversed(self.komutlar): k.geri_al(g)
    def __repr__(self):
        return "Makro(%s)" % ",".join(repr(k) for k in self.komutlar)


class Kayit:
    def __init__(self, g): self.g, self.yapilan, self.geri = g, [], []
    def calistir(self, k):
        k.uygula(self.g)
        self.yapilan.append(k)
        self.geri.clear()
    def geri_al(self):
        k = self.yapilan.pop()
        k.geri_al(self.g)
        self.geri.append(k)
    def yeniden(self):
        k = self.geri.pop()
        k.uygula(self.g)
        self.yapilan.append(k)


